// Build first-page iBox requests depending on which tool was called
const S = $('Sozlamalar').first().json;
const I = $('Asbob chaqirilganda').first().json;
const host = String(S.host).replace(/^https?:\/\//, '').replace(/\/+$/, '');
const base = `https://${host}/api/integration`;
const amal = String(I.amal || '').trim();
const TZ = 5 * 3600 * 1000;
const VER = 'v2';
const fmt = ms => new Date(ms).toISOString().slice(0, 19).replace('T', ' ');
const now = Date.now();
const tk = new Date(now + TZ);
const todayKey = tk.toISOString().slice(0, 10);
const out = [];
const kursUrl = `${base}/document/currency-exchange/list?per_page=20&page=1`;
const stock = () => String(S.oz_omborlar).split(/[\s,]+/).filter(Boolean).forEach(w => out.push({ json: {
  tur: 'zaxira', wid: Number(w),
  url: `${base}/document/stock/selection?warehouse_id=${w}&only_available=1&per_page=100&page=1` } }));

if (amal === 'abc') {
  let kun = parseInt(I.kunlar, 10); if (!(kun > 0)) kun = 30; kun = Math.min(kun, 90);
  const key = `${VER}:${kun}:${todayKey}`;
  let cached = false;
  try { const sd = $getWorkflowStaticData('global'); cached = !!(sd.abc && sd.abc.key === key); } catch (e) { }
  if (cached) {
    out.push({ json: { tur: 'kesh', kun, key, url: kursUrl } });
  } else {
    const mid = Date.UTC(tk.getUTCFullYear(), tk.getUTCMonth(), tk.getUTCDate()) - TZ;
    const from = fmt(mid - kun * 864e5), to = fmt(now);
    out.push({ json: { tur: 'sotuv', kun, key,
      url: `${base}/document/shipment/list?per_page=100&page=1&period%5Bfrom%5D=${encodeURIComponent(from)}&period%5Bto%5D=${encodeURIComponent(to)}` } });
    out.push({ json: { tur: 'kurs', kun, key, url: kursUrl } });
    stock();
  }
} else if (amal === 'qoldiq') {
  stock();
} else if (amal === 'get') {
  // Read-only guard: this host only, only under /api/integration/, GET only
  let yol = String(I.yol || '').trim();
  if (!yol.startsWith('/')) yol = '/' + yol;
  if (yol.startsWith('/api/integration/')) yol = yol.slice('/api/integration'.length);
  if (!/^\/[A-Za-z0-9_\-\/]+$/.test(yol) || yol.includes('//')) throw new Error("Noto'g'ri yo'l: " + yol);
  const pairs = [];
  for (const part of String(I.sorov || '').trim().replace(/^\?/, '').split('&')) {
    if (!part) continue;
    const i = part.indexOf('=');
    let k = i < 0 ? part : part.slice(0, i), v = i < 0 ? '' : part.slice(i + 1);
    try { k = decodeURIComponent(k); } catch (e) { }
    try { v = decodeURIComponent(v.replace(/\+/g, ' ')); } catch (e) { }
    pairs.push([k, v]);
  }
  if (!pairs.some(([k]) => k === 'per_page')) pairs.push(['per_page', '5']);
  const q = pairs.map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
  out.push({ json: { tur: 'get', url: `${base}${yol}?${q}` } });
} else {
  throw new Error("Noma'lum amal: " + amal);
}
// Catalog (category/group/brand) is fully loaded only for a fresh ABC run; otherwise one tiny request
const toliq = amal === 'abc' && out[0] && out[0].json.tur === 'sotuv';
if (out[0]) out[0].json.katalog_url = `${base}/product/list?limit=${toliq ? 500 : 1}`;
return out;

// Read page count from the first page and build the list of all page URLs
const reqs = $('Reja').all();
const out = [];
$input.all().forEach((r, i) => {
  const q = reqs[i] && reqs[i].json; if (!q) return;
  if (q.tur === 'sotuv' || q.tur === 'zaxira') {
    const last = Math.max(1, Math.min(Number(r.json.last_page) || 1, q.tur === 'sotuv' ? 500 : 300));
    for (let p = 1; p <= last; p++)
      out.push({ json: { ...q, total: Number(r.json.total) || null, last_page: last,
        url: q.url.replace(/([?&]page=)1(&|$)/, `$1${p}$2`) } });
  } else out.push({ json: q });
});
return out;

// Build the final answer: abc | qoldiq | get
const S = $('Sozlamalar').first().json;
const I = $('Asbob chaqirilganda').first().json;
const amal = String(I.amal || '').trim();
const reqs = $('Sahifalar').all();
const res = $('Hamma sahifalar').all();
const TZ = 5 * 3600 * 1000;
const todayKey = new Date(Date.now() + TZ).toISOString().slice(0, 10);
const lim = d => { const n = parseInt(I.limit, 10); return n > 0 ? Math.min(n, 3000) : d; };
const r2 = v => Math.round(v * 100) / 100;
const r3 = v => Math.round(v * 1000) / 1000;
const cl = s => String(s ?? '').replace(/[|\r\n]+/g, ' ').trim();

// ---------- get: raw response (size-limited) ----------
if (amal === 'get') {
  const all = $('Birinchi sahifa').all().map(x => x.json);
  let body = all.length === 1 ? all[0] : all;
  if (body && body.error && body.error.stack) body = { error: { message: body.error.message, status: body.error.status } };
  if (body && Array.isArray(body.links)) { body = { ...body }; delete body.links; }
  const MAX = 40000; let qisqartirildi = false;
  if (JSON.stringify(body).length > MAX) {
    qisqartirildi = true;
    const arr = Array.isArray(body) ? body : (body && Array.isArray(body.data) ? body.data : null);
    if (arr) {
      let n = arr.length;
      const wrap = k => Array.isArray(body) ? arr.slice(0, k) : { ...body, data: arr.slice(0, k) };
      while (n > 1 && JSON.stringify(wrap(n)).length > MAX) n = Math.floor(n / 2);
      body = wrap(n);
    }
    if (JSON.stringify(body).length > MAX) body = { matn: JSON.stringify(body).slice(0, MAX) };
  }
  return [{ json: { sorov: reqs[0] ? reqs[0].json.url : null, qisqartirildi, javob: body } }];
}

// ---------- stock (shared by abc and qoldiq) ----------
const st = {}; const seen = new Set(); let zaxiraXato = 0;
res.forEach((r, i) => {
  const q = reqs[i] && reqs[i].json; if (!q || q.tur !== 'zaxira') return;
  if (!Array.isArray(r.json.data)) { zaxiraXato++; return; }
  for (const x of r.json.data) {
    const key = q.wid + ':' + x.id; if (seen.has(key)) continue; seen.add(key);
    const a = Number(x.available || 0); if (a <= 0) continue;
    const p = (st[x.id] ||= { id: x.id, name: x.name, unit: x.storage_unit ? x.storage_unit.short_name : '', cat: x.product_category_name || '', total: 0, price: null, cur: null });
    p.total += a;
    const lp = x.last_purchase_price;
    if (lp && lp.price != null && p.price == null) { p.price = Number(lp.price); p.cur = lp.currency ? lp.currency.code : 'UZS'; }
  }
});

if (amal === 'qoldiq') {
  const words = String(I.qidiruv || '').toLowerCase().split(/\s+/).filter(Boolean);
  let rows = Object.values(st);
  if (words.length) rows = rows.filter(p => { const n = String(p.name || '').toLowerCase(); return words.every(w => n.includes(w)); });
  rows.sort((a, b) => String(a.name).localeCompare(String(b.name)));
  const L = lim(300);
  return [{ json: {
    sana: todayKey, filial: S.filial_nomi, omborlar: S.oz_omborlar,
    jami_topildi: rows.length, qaytarildi: Math.min(rows.length, L), xato_sahifalar: zaxiraXato,
    ustunlar: 'id|nomi|birlik|kategoriya|qoldiq|oxirgi_kelish_narxi|valyuta',
    tovarlar: rows.slice(0, L).map(p => [p.id, cl(p.name), cl(p.unit), cl(p.cat), r2(p.total), p.price ?? '', p.cur ?? ''].join('|')),
  } }];
}

// ---------- abc ----------
const meta0 = reqs[0] ? reqs[0].json : {};
let sd = null; try { sd = $getWorkflowStaticData('global'); } catch (e) { }
let pack = null;
if (meta0.tur === 'kesh' && sd && sd.abc && sd.abc.key === meta0.key) pack = sd.abc;

if (!pack) {
  // catalog: category / group / brand / type (2 = service)
  const kat = {}; let katXato = 0;
  for (const pg of $input.all()) {
    if (!Array.isArray(pg.json.data)) { katXato++; continue; }
    for (const p of pg.json.data) kat[p.id] = { name: p.name, type: Number(p.type),
      unit: p.storage_unit ? p.storage_unit.short_name : '',
      cat: p.product_category ? p.product_category.name : '', grp: p.product_group ? p.product_group.name : '',
      brand: p.product_brand ? p.product_brand.name : '' };
  }
  const num = v => { if (v == null || v === '') return null; if (typeof v === 'object') { const c = v.price ?? v.amount ?? v.value ?? v.sum; return c == null ? null : Number(c); } const n = Number(v); return isFinite(n) ? n : null; };
  let rate = null;
  res.forEach((r, i) => { const q = reqs[i] && reqs[i].json; if (!q || q.tur !== 'kurs') return;
    const a = (r.json.data || []).map(x => Number(x.exchange_rate)).filter(x => x > 1000).sort((x, y) => x - y);
    if (a.length) rate = a[Math.floor(a.length / 2)]; });

  const agg = {}, xiz = {}; const seenS = new Set();
  let docs = 0, bad = 0, usdDocs = 0, usdNoRate = 0, sotuvXato = 0, katYoq = 0; const statuslar = {};
  res.forEach((r, i) => {
    const q = reqs[i] && reqs[i].json; if (!q || q.tur !== 'sotuv') return;
    if (!Array.isArray(r.json.data)) { sotuvXato++; return; }
    for (const doc of r.json.data) {
      if (seenS.has(doc.id)) continue; seenS.add(doc.id);
      statuslar[doc.status] = (statuslar[doc.status] || 0) + 1;
      if (![23, 24].includes(Number(doc.status))) continue;
      docs++;
      const cur = doc.currency_code || 'UZS';
      if (cur !== 'UZS') usdDocs++;
      for (const l of (doc.shipment_details || [])) {
        const qty = num(l.quantity), price = num(l.price);
        let sum = num(l.total); if (sum == null && qty != null && price != null) sum = qty * price;
        let v = 0;
        if (sum == null) bad++; else if (cur === 'USD') { if (rate) v = sum * rate; else usdNoRate++; } else v = sum;
        const k = kat[l.product_id];
        const name = (l.product && l.product.name) || (k && k.name) || ('ID ' + l.product_id);
        const xizmat = k ? k.type === 2 : l.warehouse_id == null;
        const T = xizmat ? xiz : agg;
        const a = (T[l.product_id] ||= { id: l.product_id, name,
          unit: (l.product && l.product.storage_unit && l.product.storage_unit.short_name) || (k && k.unit) || '', sum: 0, qty: 0, n: 0 });
        a.sum += v; a.qty += qty || 0; a.n++;
      }
    }
  });
  let rows = Object.values(agg);
  const tot = k => rows.reduce((s, a) => s + a[k], 0);
  const mezon = tot('sum') > 0 ? 'sum' : (tot('qty') > 0 ? 'qty' : 'n');
  rows.sort((a, b) => b[mezon] - a[mezon]);
  const T = tot(mezon) || 1; let cum = 0;
  rows = rows.map(a => {
    const before = cum; cum += a[mezon];
    const s = st[a.id], k = kat[a.id]; if (!k) katYoq++;
    // [0 id, 1 name, 2 unit, 3 abc, 4 sum, 5 qty, 6 sales_count, 7 share%, 8 stock, 9 category, 10 group, 11 brand]
    return [a.id, cl(a.name), cl(a.unit), before / T < 0.8 ? 'A' : (before / T < 0.95 ? 'B' : 'C'),
      Math.round(a.sum), r2(a.qty), a.n, r3(a[mezon] / T * 100), s ? r2(s.total) : 0,
      cl(k ? k.cat : (s ? s.cat : '')), cl(k ? k.grp : ''), cl(k ? k.brand : '')];
  });
  pack = { key: meta0.key, kun: meta0.kun, sana: todayKey, rows,
    mezon: { sum: "sotuv summasi (so'm)", qty: 'sotilgan miqdor', n: 'sotuv qatorlari soni' }[mezon],
    xizmatlar: Object.values(xiz).sort((a, b) => b.sum - a.sum).slice(0, 20).map(a => `${a.id}|${cl(a.name)}|${Math.round(a.sum)}`),
    diag: { kurs: rate, hujjatlar: docs, statuslar, summasiz_qatorlar: bad, valyutali_hujjatlar: usdDocs, kurssiz_usd_qatorlar: usdNoRate,
      xato_sahifalar: sotuvXato + zaxiraXato, katalog_tovarlar: Object.keys(kat).length, katalog_xato_sahifalar: katXato, katalogda_topilmagan: katYoq } };
  // only a trustworthy result is cached (for one day)
  if (sd && mezon === 'sum' && !bad && !sotuvXato && !katXato && rows.length && Object.keys(kat).length > 1) { try { sd.abc = pack; } catch (e) { } }
}

const g = String(I.guruh || 'A').trim().toUpperCase();
const abc = ['A', 'B', 'C'].includes(g) ? g : 'HAMMASI';
const stat = {};
for (const r of pack.rows) { const s = (stat[r[3]] ||= { soni: 0, ulush_foiz: 0 }); s.soni++; s.ulush_foiz += r[7]; }
for (const k in stat) stat[k].ulush_foiz = r2(stat[k].ulush_foiz);
let sel = abc === 'HAMMASI' ? pack.rows : pack.rows.filter(r => r[3] === abc);
// short summary by product group (before text filter)
const tg = {};
for (const r of sel) { const k = (r[9] || '—') + ' / ' + (r[10] || '—'); const s = (tg[k] ||= { n: 0, sum: 0 }); s.n++; s.sum += r[4]; }
const tovar_guruhlari = Object.entries(tg).sort((a, b) => b[1].sum - a[1].sum).map(([k, v]) => `${k}|${v.n}|${Math.round(v.sum)}`);
const words = String(I.filtr || '').toLowerCase().split(/\s+/).filter(Boolean);
if (words.length) sel = sel.filter(r => { const h = (r[1] + ' ' + r[9] + ' ' + r[10] + ' ' + r[11]).toLowerCase(); return words.every(w => h.includes(w)); });
const L = lim(1000);
return [{ json: {
  sana: pack.sana, filial: S.filial_nomi, davr_kun: pack.kun, mezon: pack.mezon, keshdan: meta0.tur === 'kesh',
  jami_tovar: pack.rows.length, abc_guruhlar: stat, tanlangan: abc, filtr: words.join(' '),
  jami_topildi: sel.length, qaytarildi: Math.min(sel.length, L),
  tovar_guruhlari_ustunlar: 'kategoriya / guruh|tovarlar soni|summa', tovar_guruhlari,
  ustunlar: 'id|nomi|birlik|abc|summa|miqdor|sotuv_soni|ulush_foiz|qoldiq|kategoriya|guruh|brend',
  tovarlar: sel.slice(0, L).map(r => r.join('|')),
  hisobdan_chiqarilgan_xizmatlar: pack.xizmatlar, diagnostika: pack.diag,
} }];
